488:    private String deriveFamilyFromCode(String procedureCode) {
489:        if (procedureCode.startsWith("992")) {
490:            if (procedureCode.startsWith("9920")) {
491:                return "OFFICE_VISIT_NEW";
492:            } else {
493:                return "OFFICE_VISIT_ESTABLISHED";
494:            }
495:        } else if (procedureCode.startsWith("XR")) {
496:            return "RADIOLOGY";
497:        } else if (procedureCode.startsWith("LAB")) {
498:            return "LABORATORY";
499:        } else if (procedureCode.startsWith("TEL")) {
500:            return "TELEHEALTH";
501:        } else if (procedureCode.startsWith("PROC")) {
502:            return "PROCEDURE";
503:        }
504:        return "UNKNOWN";
505:    }
