314:    private BigDecimal applyDiscounts(String procedureCode, BigDecimal amount, PricingContext context) {
315:        BigDecimal discounted = amount;
316:
317:        if (context.getPatientAge() != null && context.getPatientAge() >= 65) {
318:            BigDecimal seniorDiscount = DISCOUNT_RULES.get("SENIOR");
319:            if (seniorDiscount != null) {
320:                discounted = discounted.multiply(seniorDiscount);
321:            }
322:        }
323:
324:        if (Boolean.TRUE.equals(context.isEmployeeDependent())) {
325:            BigDecimal employeeDiscount = DISCOUNT_RULES.get("EMPLOYEE");
326:            if (employeeDiscount != null) {
327:                discounted = discounted.multiply(employeeDiscount);
328:            }
329:        }
330:
331:        if (Boolean.TRUE.equals(context.isSelfPay())) {
332:            BigDecimal selfPayDiscount = DISCOUNT_RULES.get("SELF_PAY");
333:            if (selfPayDiscount != null) {
334:                discounted = discounted.multiply(selfPayDiscount);
335:            }
336:        }
337:
338:        if (context.hasContractedInsurance()) {
339:            BigDecimal insuranceDiscount = DISCOUNT_RULES.get("INSURANCE_CONTRACTED");
340:            if (insuranceDiscount != null) {
341:                discounted = discounted.multiply(insuranceDiscount);
342:            }
343:        }
344:
345:        String family = PROCEDURE_FAMILIES.get(procedureCode);
346:        if ("LABORATORY".equals(family) && context.getLabPanelSize() != null && context.getLabPanelSize() >= 5) {
347:            BigDecimal bulkDiscount = DISCOUNT_RULES.get("BULK_LAB");
348:            if (bulkDiscount != null) {
349:                discounted = discounted.multiply(bulkDiscount);
350:            }
351:        }
352:
353:        if (context.getCustomDiscountPercent() != null) {
354:            BigDecimal customDiscount = BigDecimal.ONE.subtract(
355:                    context.getCustomDiscountPercent().divide(new BigDecimal("100"), 4, RoundingMode.HALF_UP)
356:            );
357:            discounted = discounted.multiply(customDiscount);
358:        }
359:
360:        return discounted;
361:    }
